import boto3
import re

def parse_money(text):
    if not text:
        return None
    cleaned = re.sub(r'[^\d.-]', '', str(text))
    try:
        return float(cleaned)
    except ValueError:
        return None

def get_field_value(fields, field_type):
    for field in fields:
        if field.get('Type', {}).get('Text') == field_type:
            return field['ValueDetection']['Text']
    return None

def extract_receipt_info(image_path: str) -> dict:
    with open(image_path, 'rb') as f:
        image_bytes = f.read()

    client = boto3.client('textract', region_name='us-east-1')
    response = client.analyze_expense(
        Document={'Bytes': image_bytes}
    )

    if not response.get('ExpenseDocuments'):
        return {}

    expense_doc = response['ExpenseDocuments'][0]
    expense_fields = expense_doc.get('ExpenseFields', [])
    line_items = expense_doc.get('LineItems', [])

    merchant = get_field_value(expense_fields, 'VENDOR_NAME')

    tax_str = get_field_value(expense_fields, 'TAX_AMOUNT') or get_field_value(expense_fields, 'TAXES')
    tax = parse_money(tax_str)

    total_str = get_field_value(expense_fields, 'INVOICE_TOTAL') or get_field_value(expense_fields, 'TOTAL')
    total = parse_money(total_str)

    items = []
    for line_item in line_items:
        line_fields = line_item.get('LineItemExpenseFields', [])
        desc = get_field_value(line_fields, 'DESCRIPTION') or get_field_value(line_fields, 'ITEM')
        if not desc:
            continue
        qty_str = get_field_value(line_fields, 'QUANTITY')
        qty = parse_money(qty_str) if qty_str else None
        unit_price = parse_money(get_field_value(line_fields, 'UNIT_PRICE'))
        price = parse_money(get_field_value(line_fields, 'PRICE'))
        items.append({
            'description': desc,
            'quantity': qty,
            'unit_price': unit_price,
            'price': price
        })

    return {
        'merchant': merchant,
        'tax': tax,
        'total': total,
        'items': items
    }
